/**
 * @fileoverview Test the overriding of an existing alias
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-existing-alias-override'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const getValidTests = function () {
    return [
        {
            settings: {
                extjs: {
                    toolkit: 'classic',
                    fromVersion: '4',
                    toVersion: '7.9'
                }
            },
            code: `
                Ext.define('MyCustomClass', { xtype: 'custom-panel' });
                Ext.define('MyCustomClass', { alias: 'widget.custom.gridpanel' });
                Ext.define('MyCustomClass', { alias: 'store.custom-tree' });
                Ext.define('MyCustomClass', { alias: 'plugin.custom-mzconfigurator' });
                Ext.define('MyCustomClass', { alias: 'controller.custom-controller' });
                Ext.define('MyCustomClass', { alias: 'viewmodel.custom-colorpick-selectormodel' });
            `
        }
    ];
};

const getInvalidTests = function () {
    return [
        {
            settings: {
                extjs: {
                    fromVersion: '4',
                    toVersion: '7.9.0'
                }
            },
            code: `
                Ext.define('MyCustomClass', { xtype: 'panel' });
                Ext.define('MyCustomClass', { alias: 'widget.gridpanel' });
                Ext.define('MyCustomClass', { alias: 'store.tree' });
                Ext.define('MyCustomClass', { alias: 'plugin.mzconfigurator' });
                Ext.define('MyCustomClass', { alias: 'controller.controller' });
                Ext.define('MyCustomClass', { alias: 'viewmodel.colorpick-selectormodel' });

                // 'dashboard' did not exist in 4 but does in 7.0
                Ext.define('MyCustomClass', { xtype: 'dashboard' });

                // 'widget.widgetcolumn' did not exist in 4 but does in 7.0
                Ext.define('MyCustomClass', { alias: 'widget.widgetcolumn' });

                // 'breadcrumb' did not exist in 4 but does in 7.0
                Ext.define('MyCustomClass', { xtype: 'breadcrumb' });

                // 'store.chained' did not exist in 4 but does in 7.0
                Ext.define('MyCustomClass', { alias: 'store.chained' });
                
                // TODO - add support for this in the future
                Ext.define('MyCustomClass', function () {
                    return {
                        alias: 'store.tree'
                    };
                });
                
                // new in 7.4
                Ext.define('MyCustomClass', { alias: 'data.summary.stddev' });
                Ext.define('MyCustomClass', { alias: 'data.summary.stddevp' });
                Ext.define('MyCustomClass', { alias: 'data.summary.variance' });
                Ext.define('MyCustomClass', { alias: 'data.summary.variancep' });                
                Ext.define('MyCustomClass', { alias: 'widget.groupscolumn' });
                Ext.define('MyCustomClass', { alias: 'feature.advancedgrouping' });
                Ext.define('MyCustomClass', { alias: 'feature.advancedgroupingsummary' });
                Ext.define('MyCustomClass', { alias: 'plugin.gridfilterbar' });
                Ext.define('MyCustomClass', { alias: 'grid.filterbar.boolean' });
                Ext.define('MyCustomClass', { alias: 'grid.filterbar.date' });
                Ext.define('MyCustomClass', { alias: 'grid.filterbar.inlist' });
                Ext.define('MyCustomClass', { alias: 'grid.filterbar.list' });
                Ext.define('MyCustomClass', { alias: 'grid.filterbar.none' });
                Ext.define('MyCustomClass', { alias: 'grid.filterbar.number' });
                Ext.define('MyCustomClass', { alias: 'grid.filterbar.string' });
                Ext.define('MyCustomClass', { alias: 'plugin.operator' });
                Ext.define('MyCustomClass', { alias: 'widget.groupingpanel' });
                Ext.define('MyCustomClass', { alias: 'plugin.groupingpanel' });
            `,
            errors: [
                { message: /Override of existing alias 'widget.panel' found for 'Ext.panel.Panel'.*/ },
                { message: /Override of existing alias 'widget.gridpanel' found for 'Ext.grid.Panel'.*/ },
                { message: /Override of existing alias 'store.tree' found for 'Ext.data.TreeStore'.*/ },
                { message: /Override of existing alias 'plugin.mzconfigurator' found for 'Ext.pivot.plugin.Configurator'.*/ },
                { message: /Override of existing alias 'controller.controller' found for 'Ext.app.ViewController'.*/ },
                { message: /Override of existing alias 'viewmodel.colorpick-selectormodel' found for 'Ext.ux.colorpick.SelectorModel'.*/ },
                { message: /Override of existing alias 'widget.dashboard' found for 'Ext.dashboard.Dashboard'.*/ },
                { message: /Override of existing alias 'widget.widgetcolumn' found for 'Ext.grid.column.Widget'.*/ },
                { message: /Override of existing alias 'widget.breadcrumb' found for 'Ext.toolbar.Breadcrumb'.*/ },
                { message: /Override of existing alias 'store.chained' found for 'Ext.data.ChainedStore'.*/ },
                
                // new in 7.4
                { message: /Override of existing alias 'data.summary.stddev' found for 'Ext.data.summary.StdDev'.*/ },
                { message: /Override of existing alias 'data.summary.stddevp' found for 'Ext.data.summary.StdDevP'.*/ },
                { message: /Override of existing alias 'data.summary.variance' found for 'Ext.data.summary.Variance'.*/ },
                { message: /Override of existing alias 'data.summary.variancep' found for 'Ext.data.summary.VarianceP'.*/ },
                { message: /Override of existing alias 'widget.groupscolumn' found for 'Ext.grid.column.Groups'.*/ },     
                { message: /Override of existing alias 'feature.advancedgrouping' found for 'Ext.grid.feature.AdvancedGrouping'.*/ },   
                { message: /Override of existing alias 'feature.advancedgroupingsummary' found for 'Ext.grid.feature.AdvancedGroupingSummary'.*/ }, 
                { message: /Override of existing alias 'plugin.gridfilterbar' found for 'Ext.grid.plugin.filterbar.FilterBar'.*/ },
                { message: /Override of existing alias 'grid.filterbar.boolean' found for 'Ext.grid.plugin.filterbar.filters.Boolean'.*/ },
                { message: /Override of existing alias 'grid.filterbar.date' found for 'Ext.grid.plugin.filterbar.filters.Date'.*/ },
                { message: /Override of existing alias 'grid.filterbar.inlist' found for 'Ext.grid.plugin.filterbar.filters.InList'.*/ },
                { message: /Override of existing alias 'grid.filterbar.list' found for 'Ext.grid.plugin.filterbar.filters.List'.*/ },
                { message: /Override of existing alias 'grid.filterbar.none' found for 'Ext.grid.plugin.filterbar.filters.None'.*/ },
                { message: /Override of existing alias 'grid.filterbar.number' found for 'Ext.grid.plugin.filterbar.filters.Number'.*/ },
                { message: /Override of existing alias 'grid.filterbar.string' found for 'Ext.grid.plugin.filterbar.filters.String'.*/ },
                { message: /Override of existing alias 'plugin.operator' found for 'Ext.grid.plugin.filterbar.Operator'.*/ },
                { message: /Override of existing alias 'widget.groupingpanel' found for 'Ext.grid.plugin.grouping.Panel'.*/ },
                { message: /Override of existing alias 'plugin.groupingpanel' found for 'Ext.grid.plugin.GroupingPanel'.*/ }       
            ]
        }
    ];
};

const ruleTester = new RuleTester();
ruleTester.run('no-existing-alias-override', rule, {
    valid: getValidTests(),
    invalid: getInvalidTests()
});
